def supervised_profile(profile_id: str) -> dict[str, Any]:
    key = str(profile_id or "").strip()
    if key not in QUINTA3_SUPERVISED_PROFILES:
        raise KeyError(f"Perfil supervisionado Quinta 3 inexistente: {profile_id}")
    return deepcopy(QUINTA3_SUPERVISED_PROFILES[key])


def profile_parameters(profile_id: str) -> dict[str, Any]:
    profile = supervised_profile(profile_id)
    return {
        "unit": profile["unit"],
        "nameLines": profile["nameLines"],
        "imageCopies": profile["imageCopies"],
        "roleBounds": deepcopy(profile["roleBounds"]),
        "imageCopyBounds": deepcopy(profile["imageCopyBounds"]),
        "secondaryComponents": deepcopy(profile["secondaryComponents"]),
        "supervisedProfile": profile_id,
    }
